   if (key):find("^Zo") and type(value) == "userdata" and value.SetFont then
      local font = {value:GetFontInfo()}
      font[1] = "oblivionstylehud/media/fonts/Oblivion.ttf"
      value:SetFont(table.concat(font, "|"))
   end
end



