function OnAddOnLoaded(eventCode, addOnName)
    if addOnName ~= osi.appName then return end
	
	local defaults = {
		Icon = "Oblivion Style UI"
	}

    osi.SV = ZO_SavedVars:NewAccountWide("OblivionStyleHUD_SavedVariables", ADDON_VERSION, defaults, nil)
	
	if osi.SV.Icon == "Vanilla UI" then
		osivanilla()
	elseif osi.SV.Icon == "Oblivion Style UI" then
		osiOblivion()
	end
	
	osi:initLAM()
	
end
  
EVENT_MANAGER:RegisterForEvent(osi.appName, EVENT_ADD_ON_LOADED, OnAddOnLoaded)